import hashlib
from compile_translation import ROOT,read,write,LEADING,TRAILING
from prepare_sklcard_428 import replace_slots
T={8:['进了些新商品哦。\n','多买点带回去吧。\n'],9:['哎呀，欢迎光临。\n'],10:['今天下雨，是特卖日哦。\n一下雨就没什么客人来了。\n','所有商品都降价２成，\n多买些回去吧。\n'],
18:['哎呀，小伙子，\n咱们是头一次见吧？\n','你从城里来的？\n哎哟，那可真辛苦啊。\n','店里虽然乱糟糟的，\n还是慢慢看看吧。\n'],19:['小伙子，你从城里来的？\n哎哟，那可真辛苦啊。\n','店里虽然乱糟糟的，\n还是慢慢看看吧。\n'],
20:['来来来，瞧一瞧。\n小伙子，仔细挑挑吧。\n','这些可都是大婶引以为豪的货。\n尽管放心买吧。\n','女人靠胆量，男人靠讨喜嘛。\n帅小伙还能有赠品哦。\n啊哈哈。\n'],21:['想在咱们这儿卖东西？\n','不好意思啊…\n咱们店不收东西哦。\n','这样吧…去隔两间的“达伊达拉”\n问问如何？\n'],
22:['哎呀…好久没见巽屋的\n完二了呢。身体不舒服吗？\n','前阵子在电视上见过他，\n难道当上艺人了？\n','大婶很担心他，\n帮忙转告哦。\n'],
23:['最近没见到完二呢。\n以前常来买零食的。\n','还会教训想偷东西的孩子…\n真是个好孩子啊。\n','买远足带的零食，\n也严格遵守预算呢…啊哈哈。\n'],24:['说起来，完二来买过东西呢。\n','他说交到了很帅气的前辈…\n笑得可高兴了。\n','之前一直闷闷不乐的，\n大婶这下可放心了。\n'],
25:['那么，今天要买什么？\n','小伙子，你老买些奇怪的东西…\n大婶有点担心啊。\n','去林间学校带多余的东西，\n会被老师骂哦。啊哈哈。\n'],26:['对了，你们去林间学校了吧？\n好多孩子提着行李走过呢。\n','哎…被推下瀑布？\n从高处跳下去了？\n','真淘气啊～\n啊哈哈哈哈。\n'],
27:['最近有些怪人来打听\n理世的各种事情呢。\n','问她以前是什么样，\n有没有照片之类的…\n','理世退出演艺圈，\n有那么罪大恶极吗？\n','丸久家也得做生意啊…\n他们说真是难办呢。\n'],28:['丸久家的理世，\n最近没见到了呢。\n','不当艺人了，也还是很辛苦吧？\n连咱们这儿都有怪记者来呢。\n','是不是该进点防身用品了…\n','小伙子，你们见到理世，\n帮我问问她要不要吧。\n'],
29:['来来，今天要买什么？\n哎呀，还拿不定主意吗？\n','要不学学隔壁的理世，\n大婶也给你现场示范推销？\n','啊哈哈，开玩笑的！\n慢慢挑吧。\n'],30:['哎呀…小伙子。\n…可怜见的，受苦了吧？\n','你们班主任被杀了吧？\n…我听别的孩子说了…\n','真是的…怎么会\n这么不太平呢。\n'],31:['暑假过得开心吗？\n','…每天都很忙？\n上了高中，也真不容易啊。\n','觉得热了，随时来\n乘凉啊。啊哈哈。\n'],
32:['最近夜里也能听到铃虫叫了，\n夏天快结束了呢。\n','小伙子，作业和\n图画日记都写好了吗？\n','…没有图画日记？\n哎呀，真是的～啊哈哈哈。\n'],33:['哎呀，看着很开心嘛？\n要去哪儿吗？\n','修学旅行…去城里？\n…哎哟，真不错啊。\n','大婶不了解城里的事，\n真羡慕你们呢。\n','等着你的伴手礼哦！\n啊哈哈哈。\n'],
34:['城里怎么样？\n久违地回去玩得开心吗？\n','城里的便利店…是２４小时\n营业的吧？\n','店员可真辛苦啊…\n','对了，有没有卖什么\n有趣的东西啊？\n'],35:['这就是“侦探王子”的效应吗…\n前阵子电视台来采访了。\n','说想把咱们店放进\n“王子走访店铺百选”…我当然拒绝了。\n','比起游客，我更想招待\n你们这样的孩子嘛…啊哈哈。\n'],
36:['最近，朱尼斯一个叫熊田的\n可爱孩子经常来买东西呢。\n','说是你们推荐了这家店，\n然后就成了忠实顾客。\n','大婶可高兴了…\n谢谢你们啊。\n'],37:['入秋了，差不多该在店里\n摆些新米了吧。\n','还是说…柿饼…\n不对…松茸呢？\n','别看大婶这样，也有想过\n改变风格哦。啊哈哈哈。\n'],38:['哎呀…小伙子，\n今天看起来很忙啊。\n','…准备文化祭？\n是啊，又到这个时候了。\n','大婶每年都很期待呢。\n有海报的话，随时拿来贴哦。\n'],
39:['我去看文化祭了哦。\n小伙子，你穿女装了吧？\n','啊哈哈，大婶我啊，\n还给你投票了呢！\n','下次叫上街坊邻居，\n一起去看吧。啊哈哈。\n'],40:['…小伙子，看着不舒服，\n没事吧？\n','有什么烦心事吗？\n有好好睡觉吗？\n','身体才是本钱啊…\n可别逞强哦。\n'],41:['哎呀，小伙子。\n怎么了？脸色这么差？\n','…菜菜子的情况不好吗？\n','虽然担心，身体也是本钱啊…\n可别逞强哦。\n'],
42:['…大婶最近总觉得身体不舒服。\n','小伙子，你也要注意啊。\n这雾…总觉得让人不舒服…\n'],43:['啊…真冷啊。\n都到年末了，也没办法啊。\n','去商店街开会，\n好多人都感冒了呢。\n','小伙子，你也要注意哦。\n'],44:['哎呀，好久不见了。\n最近过得好吗？\n','…这样啊。你要离开这里了…\n真舍不得啊。\n','以后再来这边，\n记得来店里看看哦。\n'],
45:['你问有没有孩子\n在这里打过工？\n','大婶自己就能看店，\n所以没雇过打工的孩子哦。\n','不好意思啊。\n'],46:['哎呀，小伙子。\n外面的雾终于散了呢。\n','之前总让人不舒服呢。\n大婶这下也放心了。\n','要是你们出了什么事，\n我可是会担心的啊。\n'],47:['真冷啊，冻死人了。\n听说今年特别冷呢。\n','大婶年轻时，也会在\n雪地里跑来跑去地玩…\n','到了这个年纪，可就不行了。\n啊哈哈哈。\n'],
48:['今年也快结束了啊。\n真是一眨眼的事。\n','有你和朋友们来光顾，\n大婶今年可开心了。\n','明年也要\n再来玩哦。\n'],49:['好好，\n新年快乐啊。\n','小伙子，收了\n不少压岁钱吧？\n','今年也记得\n多来咱们店买东西哦。\n'],50:['哎呀，小伙子。\n欢迎你来啊。\n','过完年之后，\n一下就安静下来了啊。\n','来来，外头很冷吧？\n在店里暖和暖和再走。\n']}
EXTRA={(51,2):'……啊！\n',(51,3):'真是的，大婶我啊，\n竟然睁着眼就睡着了…啊哈哈。\n'}

def main():
    T[46][2]='要是你们出了什么事，\n我会担心的啊。\n'
    s='export_base/facility/msg_item.bmd.json';doc=read(ROOT/s)
    target=ROOT/'translation/batches/433_item_shop_legacy.generated.json';assert not target.exists()
    catalog={r['key']:r for r in read(ROOT/'translation/catalog.working.json')};rows=[]
    text={(i,j):t for i,ls in T.items() for j,t in enumerate(ls)};text.update(EXTRA)
    for (i,j),plain in text.items():
        r=catalog[f'{s}:{i}:{j}'];assert not r.get('translation');old=r['original']
        full=replace_slots(old,plain);prefix=LEADING.match(old).group();suffix=TRAILING.search(old).group()
        body=full[len(prefix):len(full)-len(suffix)];assert prefix+body+suffix==full
        rows.append([i,j,doc['texts'][i]['id'],body])
    write(target,dict(status='draft',sources={s:rows},source_hashes={s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest()},review_notes=['道具店108页旧作日常对话补全；保留逐字控制及分页。两成降价保留数字２，不反译成二折。','含旧作剧情，未验证PQ可达性。']))
    print('Item shop pages:',len(rows))
if __name__=='__main__':main()
